{
  "recipe_id": "appam-03",
  "title": "Appam (lace-edged fermented rice hoppers)",
  "ingredients": [
    {
      "name": "Raw rice (pachari), soaked",
      "amount": "500g"
    },
    {
      "name": "Cooked rice",
      "amount": "100g"
    },
    {
      "name": "Fresh thick coconut milk",
      "amount": "400g"
    },
    {
      "name": "Fresh toddy (or 1g instant yeast + 10g sugar in warm water)",
      "amount": "100g"
    },
    {
      "name": "Sugar",
      "amount": "15g"
    },
    {
      "name": "Fine sea salt",
      "amount": "7g"
    }
  ],
  "method": "Soak the raw rice 4 hours, then grind with the cooked rice and half the\ncoconut milk to a completely smooth batter. Stir in the toddy (or the yeast\nmixture) and the sugar, and ferment 8 hours at room temperature until bubbly\nand risen. Just before cooking, stir in the remaining coconut milk and the 7g\nfine sea salt; the batter should coat a spoon thinly. Heat an appachatti,\npour in a small ladleful, and immediately lift and swirl the pan in one full\ncircle so the batter climbs the walls — this makes the crisp lace edge with\nthe soft, spongy centre. Cover and cook 2 minutes; the appam is done when the\nedges release and the centre springs back."
}

{
  "recipe_id": "thayir-04",
  "title": "Thayir — Homemade Curd (set overnight)",
  "ingredients": [
    {
      "name": "Whole milk (full-fat)",
      "amount": "1000g"
    },
    {
      "name": "Live curd from the previous batch",
      "amount": "30g"
    }
  ],
  "method": "Bring the milk just to a boil, then simmer 5 minutes to concentrate it\nslightly — this gives a thicker set. Cool to 40–43°C: the milk should feel\ndistinctly warm, not hot, on a clean fingertip held for ten seconds. Whisk\nthe starter curd until smooth, stir it through the milk, cover, and leave\ncompletely undisturbed for 6 to 8 hours at around 30°C. In cold weather, set\nthe pot inside a switched-off oven with the light on, or wrap it in a thick\ntowel next to a hot-water bottle. The curd is set when it jiggles as one mass\nand the surface releases a little clear whey. Refrigerate immediately once\nset; over-fermenting at room temperature turns it sharply sour by evening.\nSave 30g as the starter for tomorrow's batch."
}

{
  "recipe_id": "kadumanga-06",
  "title": "Kadumanga Achar (Kerala fermented tender mango pickle)",
  "ingredients": [
    {
      "name": "Tender baby mangoes (kannimanga), whole",
      "amount": "1000g"
    },
    {
      "name": "Crystal sea salt",
      "amount": "150g"
    },
    {
      "name": "Kashmiri chilli powder",
      "amount": "50g"
    },
    {
      "name": "Gingelly (sesame) oil",
      "amount": "60g"
    },
    {
      "name": "Mustard seeds",
      "amount": "10g"
    },
    {
      "name": "Fenugreek powder, roasted",
      "amount": "5g"
    },
    {
      "name": "Asafoetida (hing)",
      "amount": "3g"
    }
  ],
  "method": "Wipe the mangoes dry — no water must touch them at any stage. Layer them\nwith the crystal salt in a sterilised bharani (ceramic pickle jar), close,\nand shake once daily. Over 10 to 14 days the salt draws out the mango's own\nbrine and the fruit ferments in it, turning olive-drab and pleasantly tangy.\nThen heat the gingelly oil, crackle the mustard seeds, switch off the heat,\nand stir in the chilli powder, fenugreek powder and asafoetida. Cool the\nspiced oil completely and fold it through the mangoes and their brine.\nReturn everything to the bharani. The pickle is eatable in a week but\nmatures over a month; it keeps a year at room temperature if only dry\nspoons ever enter the jar."
}

{
  "recipe_id": "idli-batter-01",
  "title": "Idli Batter (2kg batch)",
  "ingredients": [
    {
      "name": "Idli rice (parboiled)",
      "amount": "1000g"
    },
    {
      "name": "Whole white urad dal",
      "amount": "250g"
    },
    {
      "name": "Fenugreek seeds",
      "amount": "10g"
    },
    {
      "name": "Rock salt",
      "amount": "20g"
    },
    {
      "name": "Water for grinding",
      "amount": "~720g"
    }
  ],
  "method": "Wash and soak the rice and the urad dal separately for 4 to 6 hours, with the\nfenugreek seeds in the dal bowl. Grind the dal first with ice-cold water until\nlight, fluffy and tripled in volume — it should hold a soft peak. Grind the\nrice to a fine rava-like texture, slightly grainy between the fingers. Combine\nboth with the rock salt and mix by hand for a full 2 minutes; the warmth of\nyour hand kick-starts the wild fermentation. Ferment 8 to 12 hours at 28–32°C\nuntil doubled and domed. Do not stir the risen batter. Scoop gently into\ngreased idli moulds and steam 12 minutes; rest 2 minutes before unmoulding."
}

{
  "recipe_id": "dosa-batter-02",
  "title": "Crisp Dosa Batter",
  "ingredients": [
    {
      "name": "Dosa rice (raw, short-grain)",
      "amount": "750g"
    },
    {
      "name": "Whole white urad dal",
      "amount": "250g"
    },
    {
      "name": "Chana dal",
      "amount": "30g"
    },
    {
      "name": "Fenugreek seeds",
      "amount": "8g"
    },
    {
      "name": "Thick poha (flattened rice)",
      "amount": "50g"
    },
    {
      "name": "Fine sea salt",
      "amount": "18g"
    }
  ],
  "method": "Soak rice, urad dal, chana dal and fenugreek together for 5 hours; soak the\npoha separately for the last 30 minutes. Grind everything to a smooth, flowing\nbatter — thinner than idli batter — adding water a little at a time. Stir in\nthe salt and ferment 10 to 14 hours at 26–30°C until risen by half and sour-\nsmelling. Thin with water to pouring-cream consistency. Heat a cast-iron tawa\nuntil a water drop dances, wipe with an oiled onion half, pour a ladleful in\nthe centre and spiral outward with the ladle base to a thin, even round.\nDrizzle the edges with gingelly oil and cook until deep gold and crisp; a\nproper dosa releases itself from the pan."
}

{
  "recipe_id": "ragi-koozh-05",
  "title": "Ragi Koozh (fermented finger-millet porridge)",
  "ingredients": [
    {
      "name": "Ragi (finger millet) flour",
      "amount": "300g"
    },
    {
      "name": "Broken rice (noi arisi)",
      "amount": "100g"
    },
    {
      "name": "Water",
      "amount": "1500g"
    },
    {
      "name": "Rock salt",
      "amount": "12g"
    }
  ],
  "method": "Whisk the ragi flour into 500g of the water until lump-free, and leave the\nslurry overnight — 10 to 12 hours — in a clay pot at room temperature to\nferment; by morning it smells pleasantly sour and shows fine bubbles. Cook\nthe broken rice in the remaining 1000g of water until completely soft. Stir\nthe fermented ragi slurry into the simmering rice in a steady stream,\nwhisking constantly, and cook 8 to 10 minutes until the porridge thickens\nand turns glossy chocolate-brown. Add the rock salt at the end. Cool to\nlukewarm and thin with water to a drinkable consistency. Traditionally\nenjoyed the next day, when a second, gentler fermentation in the pot deepens\nthe sourness — this is summer street food, sold cold from mud pots."
}
